class AppConfig {
  /// 通过 `--dart-define=API_BASE_URL=https://...` 指定。
  static const apiBaseUrl = String.fromEnvironment(
    'API_BASE_URL',
    defaultValue: 'http://127.0.0.1:8080/',
  );

  static const appVersion = '0.1.0';
}

import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// 安全存储令牌：Android Keystore / iOS Keychain。
class TokenStore {
  TokenStore([FlutterSecureStorage? storage])
      : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _accessKey = 'access_token';
  static const _refreshKey = 'refresh_token';

  Future<String?> accessToken() => _storage.read(key: _accessKey);

  Future<String?> refreshToken() => _storage.read(key: _refreshKey);

  Future<void> save({required String access, required String refresh}) async {
    await _storage.write(key: _accessKey, value: access);
    await _storage.write(key: _refreshKey, value: refresh);
  }

  Future<void> clear() async {
    await _storage.delete(key: _accessKey);
    await _storage.delete(key: _refreshKey);
  }
}

import 'package:dio/dio.dart';

import '../config.dart';
import '../storage/token_store.dart';

class ApiException implements Exception {
  ApiException(this.message, {this.code, this.statusCode});

  final String message;
  final String? code;
  final int? statusCode;

  @override
  String toString() => message;
}

/// 统一 HTTP 客户端：附加令牌、错误码转中文、预留 401 刷新入口。
class ApiClient {
  ApiClient({required TokenStore tokenStore, Dio? dio})
      : _tokenStore = tokenStore,
        _dio = dio ??
            Dio(
              BaseOptions(
                baseUrl: AppConfig.apiBaseUrl,
                connectTimeout: const Duration(seconds: 10),
                receiveTimeout: const Duration(seconds: 20),
                headers: {'Content-Type': 'application/json'},
              ),
            ) {
    _dio.interceptors.add(
      InterceptorsWrapper(
        onRequest: (options, handler) async {
          if (options.extra['noAuth'] != true) {
            final token = await _tokenStore.accessToken();
            if (token != null && token.isNotEmpty) {
              options.headers['Authorization'] = 'Bearer $token';
            }
          }
          handler.next(options);
        },
        onError: (error, handler) {
          handler.next(error);
        },
      ),
    );
  }

  final Dio _dio;
  final TokenStore _tokenStore;

  Dio get raw => _dio;

  Future<Map<String, dynamic>> getJson(String path,
      {Map<String, dynamic>? query}) async {
    return _request(() => _dio.get<Map<String, dynamic>>(path, queryParameters: query));
  }

  Future<Map<String, dynamic>> postJson(
    String path,
    Map<String, dynamic> body, {
    bool noAuth = false,
  }) async {
    return _request(
      () => _dio.post<Map<String, dynamic>>(
        path,
        data: body,
        options: Options(extra: {'noAuth': noAuth}),
      ),
    );
  }

  Future<Map<String, dynamic>> putJson(
    String path,
    Map<String, dynamic> body,
  ) async {
    return _request(() => _dio.put<Map<String, dynamic>>(path, data: body));
  }

  Future<void> delete(String path) async {
    await _request(() => _dio.delete<Map<String, dynamic>>(path));
  }

  Future<Map<String, dynamic>> _request(
    Future<Response<Map<String, dynamic>>> Function() call,
  ) async {
    try {
      final response = await call();
      return response.data ?? <String, dynamic>{};
    } on DioException catch (error) {
      throw _mapError(error);
    }
  }

  ApiException _mapError(DioException error) {
    final data = error.response?.data;
    if (data is Map && data['message'] is String) {
      return ApiException(
        data['message'] as String,
        code: data['code'] as String?,
        statusCode: error.response?.statusCode,
      );
    }
    if (error.type == DioExceptionType.connectionTimeout ||
        error.type == DioExceptionType.receiveTimeout ||
        error.type == DioExceptionType.connectionError) {
      return ApiException('网络连接失败，请检查网络后重试');
    }
    return ApiException(
      '请求失败（${error.response?.statusCode ?? '未知'}）',
      statusCode: error.response?.statusCode,
    );
  }
}

class LoginResult {
  LoginResult({
    required this.accessToken,
    required this.refreshToken,
    required this.expiresIn,
  });

  final String accessToken;
  final String refreshToken;
  final int expiresIn;

  factory LoginResult.fromJson(Map<String, dynamic> json) => LoginResult(
        accessToken: json['access_token'] as String,
        refreshToken: json['refresh_token'] as String,
        expiresIn: (json['expires_in'] as num?)?.toInt() ?? 0,
      );
}

class Child {
  Child({
    required this.id,
    required this.nickname,
    required this.stage,
    this.birthYear,
    this.birthMonth,
    this.gradeTag,
  });

  final String id;
  final String nickname;
  final String stage;
  final int? birthYear;
  final int? birthMonth;
  final String? gradeTag;

  factory Child.fromJson(Map<String, dynamic> json) => Child(
        id: json['id'] as String,
        nickname: json['nickname'] as String? ?? '孩子',
        stage: json['stage'] as String? ?? 'low',
        birthYear: (json['birth_year'] as num?)?.toInt(),
        birthMonth: (json['birth_month'] as num?)?.toInt(),
        gradeTag: json['grade_tag'] as String?,
      );
}

class DeviceInfo {
  DeviceInfo({
    required this.id,
    required this.deviceId,
    required this.platform,
    required this.childId,
    required this.childName,
    this.boundAt,
  });

  final String id;
  final String deviceId;
  final String platform;
  final String childId;
  final String childName;
  final DateTime? boundAt;

  factory DeviceInfo.fromJson(Map<String, dynamic> json) => DeviceInfo(
        id: json['id'] as String,
        deviceId: json['device_id'] as String? ?? '',
        platform: json['platform'] as String? ?? 'tv',
        childId: json['child_id'] as String? ?? '',
        childName: json['child_name'] as String? ?? '',
        boundAt: DateTime.tryParse(json['bound_at'] as String? ?? ''),
      );
}

import 'package:flutter/material.dart';

class AppTheme {
  static const seed = Color(0xFF1B8A6B);

  static ThemeData light() {
    final scheme = ColorScheme.fromSeed(seedColor: seed, brightness: Brightness.light);
    return ThemeData(
