import {
  AppstoreOutlined,
  AuditOutlined,
  CloudUploadOutlined,
  DatabaseOutlined,
  LogoutOutlined,
  PieChartOutlined,
} from '@ant-design/icons'
import { Button, Layout, Menu, Spin, Typography } from 'antd'
import { useEffect, useState } from 'react'
import {
  Navigate,
  Route,
  Routes,
  useLocation,
  useNavigate,
} from 'react-router-dom'
import { api, tokenStore } from './api'
import { AuthContext } from './auth'
import type { AdminPrincipal } from './types'
import AuditPage from './pages/AuditPage'
import CoveragePage from './pages/CoveragePage'
import ImportPage from './pages/ImportPage'
import Login from './pages/Login'
import QuestionEdit from './pages/QuestionEdit'
import Questions from './pages/Questions'

const { Header, Sider, Content } = Layout

export default function App() {
  const [principal, setPrincipal] = useState<AdminPrincipal | null>(null)
  const [loading, setLoading] = useState(Boolean(tokenStore.get()))
  const navigate = useNavigate()
  const location = useLocation()

  useEffect(() => {
    if (!tokenStore.get()) {
      setLoading(false)
      return
    }
    void (async () => {
      try {
        setPrincipal(await api.me())
      } catch {
        tokenStore.clear()
      } finally {
        setLoading(false)
      }
    })()
  }, [])

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'grid', placeItems: 'center' }}>
        <Spin size="large" />
      </div>
    )
  }

  if (!principal) {
    return <Login onLogin={setPrincipal} />
  }

  const can = (permission: string) =>
    principal.permissions?.includes('*') || principal.permissions?.includes(permission)

  const selected = location.pathname.startsWith('/questions')
    ? '/questions'
    : location.pathname

  return (
    <AuthContext.Provider value={{ principal, can }}>
      <Layout style={{ minHeight: '100vh' }}>
        <Sider theme="light" width={200}>
          <div style={{ padding: 20 }}>
            <Typography.Title level={4} style={{ margin: 0 }}>
              OpenQuizGo
            </Typography.Title>
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              题库治理后台
            </Typography.Text>
          </div>
          <Menu
            mode="inline"
            selectedKeys={[selected]}
            onClick={({ key }) => navigate(key)}
            items={[
              { key: '/questions', icon: <DatabaseOutlined />, label: '题目管理' },
              {
                key: '/import',
                icon: <CloudUploadOutlined />,
                label: '批量导入',
                disabled: !can('question.import'),
              },
              {
                key: '/coverage',
                icon: <PieChartOutlined />,
                label: '覆盖率',
              },
              {
                key: '/audit',
                icon: <AuditOutlined />,
                label: '审计日志',
                disabled: !can('audit.read'),
              },
            ]}
          />
        </Sider>
        <Layout>
          <Header
            style={{
              background: '#fff',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              paddingInline: 24,
            }}
          >
            <Typography.Text>
              <AppstoreOutlined /> 题库治理
            </Typography.Text>
            <span>
              <Typography.Text style={{ marginRight: 16 }}>
                {principal.display_name || principal.username}
              </Typography.Text>
              <Button
                icon={<LogoutOutlined />}
                onClick={() => {
                  tokenStore.clear()
                  setPrincipal(null)
                }}
              >
                退出
              </Button>
            </span>
          </Header>
          <Content style={{ padding: 24, background: '#f5f7f6' }}>
            <Routes>
              <Route path="/" element={<Navigate to="/questions" replace />} />
              <Route path="/questions" element={<Questions />} />
              <Route path="/questions/new" element={<QuestionEdit />} />
              <Route path="/questions/:id" element={<QuestionEdit />} />
              <Route path="/import" element={<ImportPage />} />
              <Route path="/audit" element={<AuditPage />} />
              <Route path="/coverage" element={<CoveragePage />} />
            </Routes>
          </Content>
        </Layout>
      </Layout>
    </AuthContext.Provider>
  )
}
