		returning id`).Scan(&id)
	if err != nil {
		t.Fatalf("insert topic pack: %v", err)
	}
	return id
}

func hasWarning(warnings []string, want string) bool {
	for _, warning := range warnings {
		if warning == want {
			return true
		}
	}
	return false
}
