            {'id': 'b', 'text': '6'},
          ],
        }
      ],
      'child_score': childScore,
      'parent_score': parentScore,
      if (finished) 'result': {
        'winner': 'child',
        'child_score': childScore,
        'parent_score': parentScore,
      },
      if (finished)
        'answers': [
          {
