      request.response.headers.contentType = ContentType.json;
      final path = request.uri.path;
      if (request.method == 'GET' && path.endsWith('/membership')) {
        request.response.write(jsonEncode({'plans': [_plan()]}));
      } else if (request.method == 'GET' && path.endsWith('/orders')) {
        request.response.write(jsonEncode({
          'items': [
            {
              'id': 'o1',
              'order_no': 'M1',
              'plan_name': '月度会员',
              'amount_cents': 1990,
              'duration_days': 30,
              'status': 'paid',
              'created_at': '2026-11-04T10:00:00+08:00',
              'paid_at': '2026-11-04T10:00:05+08:00',
            }
          ]
        }));
      } else if (request.method == 'POST' && path.endsWith('/orders')) {
        submitted = jsonDecode(await utf8.decoder.bind(request).join())
            as Map<String, dynamic>;
        request.response.write(jsonEncode({
          'id': 'o2',
          'order_no': 'M2',
          'plan_name': '月度会员',
          'amount_cents': 1990,
          'duration_days': 30,
          'status': 'pending',
          'created_at': '2026-11-04T11:00:00+08:00',
        }));
      } else if (request.method == 'POST' && path.endsWith('/pay')) {
        request.response.write(jsonEncode({
          'order': {
            'id': 'o2',
            'order_no': 'M2',
            'plan_name': '月度会员',
            'amount_cents': 1990,
            'duration_days': 30,
            'status': 'paid',
            'created_at': '2026-11-04T11:00:00+08:00',
