import {
  Button,
  Card,
  Popconfirm,
  Select,
  Space,
  Table,
  Tag,
  Typography,
  message,
} from 'antd'
import type { ColumnsType } from 'antd/es/table'
import { useEffect, useState } from 'react'
import { api, ApiError } from '../api'
import { useAuth } from '../auth'
import type { MembershipOrder } from '../types'

const statusLabel: Record<string, string> = {
  pending: '待支付',
  paid: '已支付',
  cancelled: '已取消',
  refunded: '已退款',
}
const statusColor: Record<string, string> = {
  pending: 'processing',
  paid: 'success',
  cancelled: 'default',
  refunded: 'orange',
}

function yuan(cents: number) {
  return `¥${(cents / 100).toFixed(2)}`
}

export default function MembershipOrdersPage() {
  const { can } = useAuth()
  const [orders, setOrders] = useState<MembershipOrder[]>([])
  const [total, setTotal] = useState(0)
  const [status, setStatus] = useState<string | undefined>()
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [refunding, setRefunding] = useState<string | null>(null)
  const pageSize = 20

  const load = async (nextPage = page, nextStatus = status) => {
    setLoading(true)
    try {
      const result = await api.membershipOrders({
        status: nextStatus,
        limit: pageSize,
        offset: (nextPage - 1) * pageSize,
      })
      setOrders(result.items || [])
      setTotal(result.total || 0)
    } catch (error) {
      message.error(error instanceof ApiError ? error.message : '加载失败')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const refund = async (order: MembershipOrder) => {
    setRefunding(order.id)
    try {
      await api.refundMembershipOrder(order.id)
      message.success(`订单 ${order.order_no} 已退款`)
      await load()
    } catch (error) {
      message.error(error instanceof ApiError ? error.message : '退款失败')
    } finally {
      setRefunding(null)
    }
  }

  const columns: ColumnsType<MembershipOrder> = [
    {
      title: '订单号',
      dataIndex: 'order_no',
      width: 220,
      render: (value: string) => <Typography.Text copyable>{value}</Typography.Text>,
    },
    { title: '套餐', dataIndex: 'plan_name', width: 140 },
    {
      title: '金额',
      dataIndex: 'amount_cents',
      width: 100,
      render: (value: number) => yuan(value),
    },
    {
      title: '状态',
      dataIndex: 'status',
      width: 100,
      render: (value: string) => (
        <Tag color={statusColor[value] || 'default'}>{statusLabel[value] || value}</Tag>
      ),
    },
    {
      title: '创建时间',
      dataIndex: 'created_at',
      width: 170,
      render: (value: string) => new Date(value).toLocaleString(),
    },
    {
      title: '支付时间',
      dataIndex: 'paid_at',
      width: 170,
      render: (value?: string) => (value ? new Date(value).toLocaleString() : '—'),
    },
    {
      title: '操作',
      width: 100,
      render: (_, order) =>
        order.status === 'paid' ? (
          <Popconfirm
            title={`退款订单 ${order.order_no}？`}
            description="退款会回退会员到期时间，可能导致权益失效。"
            okText="退款"
            cancelText="取消"
            onConfirm={() => void refund(order)}
            disabled={!can('membership.write')}
          >
            <Button
              type="link"
              danger
              loading={refunding === order.id}
              disabled={!can('membership.write')}
            >
              退款
            </Button>
          </Popconfirm>
        ) : order.status === 'refunded' ? (
          <Typography.Text type="secondary">
            {order.refunded_at ? new Date(order.refunded_at).toLocaleDateString() : '已退款'}
          </Typography.Text>
        ) : (
          '—'
        ),
    },
  ]

  return (
    <Card>
      <Space style={{ marginBottom: 16 }} wrap>
        <Typography.Title level={4} style={{ margin: 0 }}>
          会员订单
        </Typography.Title>
        <Select
          allowClear
          placeholder="全部状态"
          style={{ width: 140 }}
          options={Object.entries(statusLabel).map(([value, label]) => ({ value, label }))}
          onChange={(value) => {
            setStatus(value)
            setPage(1)
            void load(1, value)
          }}
        />
        <Typography.Text type="secondary">退款为模拟操作，回退对应时长</Typography.Text>
      </Space>
      <Table
        rowKey="id"
        loading={loading}
        columns={columns}
        dataSource={orders}
        scroll={{ x: 1100 }}
        pagination={{
          current: page,
          pageSize,
          total,
          showSizeChanger: false,
          onChange: (next) => {
            setPage(next)
            void load(next)
          },
        }}
        locale={{ emptyText: '还没有会员订单' }}
      />
    </Card>
  )
}

