		clean = append(clean, id)
	}
	if len(clean) == 0 {
		return CalibrationRollbackResult{}, newAPIError(422, "VALIDATION_ERROR", "题目数量需在 1–200 之间")
	}
	return s.repo.rollbackCalibration(ctx, clean, principal.ID, ip)
}

