	rows, err := r.pool.Query(ctx, `
		select to_char(captured_on, 'YYYY-MM-DD'), total, online, draft, in_review, offline
		from coverage_snapshot
		where captured_on >= current_date - $1
		order by captured_on`, days)
	if err != nil {
